CREATE PROCEDURE "DP_FORECAST_LR" (IN TBL_NAME NVARCHAR(100), IN CONTROLTBL_NAME NVARCHAR(100),OUT RESULT TABLE (GROUPID VARCHAR (100), TIMESTAMP INT, VALUE DOUBLE)) LANGUAGE SQLSCRIPT  SQL SECURITY INVOKER   AS  BEGIN         DECLARE FORECASTSLR_CONTROL TABLE ("NAME" VARCHAR (50), "INTARGS" INTEGER, "DOUBLEARGS" DOUBLE, "STRINGARGS" VARCHAR (100));     DECLARE FORECASTSLR_OUTPARAMETER TABLE ("NAME" VARCHAR (50), "VALUE" DOUBLE);     DECLARE FORECASTSLR_RESULT TABLE ("TIMESTAMP" INTEGER, "VALUE" DOUBLE);     DECLARE DATA_TABLE TABLE("GROUPID" VARCHAR (100), "TIMESTAMP" INT, "VALUE" DOUBLE);     DECLARE LR_DATA_TABLE TABLE("TIMESTAMP" INT, "Y" DOUBLE);     DECLARE ROWCNT INT;     DECLARE ROWINDEX INT;     DECLARE GROUPCNT INT;     DECLARE GROUPID VARCHAR (100);          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#SOURCEDATAHD73Y4GFKV093JDU';     IF ROWCNT>0 THEN         DROP TABLE #SOURCEDATAHD73Y4GFKV093JDU;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #SOURCEDATAHD73Y4GFKV093JDU LIKE PAL_MULTIPLEFORECASTSMOOTHING_DATA_T;     EXECUTE IMMEDIATE 'INSERT INTO #SOURCEDATAHD73Y4GFKV093JDU SELECT * FROM '||:TBL_NAME;     DATA_TABLE=SELECT * FROM #SOURCEDATAHD73Y4GFKV093JDU;          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMPPALFORECASTSLRCONTROL';     IF ROWCNT>0 THEN     DROP TABLE #TEMPPALFORECASTSLRCONTROL;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMPPALFORECASTSLRCONTROL LIKE PAL_FORECASTSLR_CONTROL_T;          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMPGROUPID';     IF ROWCNT>0 THEN         DROP TABLE #TEMPGROUPID;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMPGROUPID ("GROUPID" VARCHAR (100), "MAXVALUE" DOUBLE);     INSERT INTO #TEMPGROUPID SELECT GROUPID, MAX("VALUE") AS MAXVALUE FROM :DATA_TABLE GROUP BY GROUPID;          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMPOUTPUTRESULT';     IF ROWCNT>0 THEN         DROP TABLE #TEMPOUTPUTRESULT;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMPOUTPUTRESULT LIKE PAL_MULTIPLEFORECAST_T;          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMPOUTPARAMETER';     IF ROWCNT>0 THEN         DROP TABLE #TEMPOUTPARAMETER;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMPOUTPARAMETER LIKE MULTIPLEFORECAST_OUTPARAMETER_T;          SELECT COUNT(*) INTO ROWCNT FROM #TEMPGROUPID;     FOR ROWINDEX IN 0 .. :ROWCNT-1 DO         SELECT "GROUPID" INTO GROUPID FROM #TEMPGROUPID LIMIT 1 OFFSET :ROWINDEX;          SELECT MAX("TIMESTAMP") INTO GROUPCNT FROM :DATA_TABLE WHERE GROUPID=:GROUPID;                  TRUNCATE TABLE #TEMPPALFORECASTSLRCONTROL;         EXECUTE IMMEDIATE 'INSERT INTO #TEMPPALFORECASTSLRCONTROL SELECT "NAME", "INTARGS", "DOUBLEARGS", "STRINGARGS" FROM '||:CONTROLTBL_NAME || ' WHERE GROUPID = '''|| :GROUPID ||'''';              LR_DATA_TABLE=SELECT "TIMESTAMP", "VALUE" AS Y FROM :DATA_TABLE WHERE GROUPID=:GROUPID;         FORECASTSLR_CONTROL=SELECT * FROM #TEMPPALFORECASTSLRCONTROL;         CALL PALLRWITHSEASONALADJUST_PROC(:LR_DATA_TABLE, :FORECASTSLR_CONTROL, :FORECASTSLR_OUTPARAMETER, :FORECASTSLR_RESULT) ;          INSERT INTO #TEMPOUTPUTRESULT ("GROUPID", "TIMESTAMP", "VALUE") SELECT :GROUPID AS GROUPID, "TIMESTAMP", "VALUE" FROM :FORECASTSLR_RESULT WHERE TIMESTAMP>:GROUPCNT;         INSERT INTO #TEMPOUTPARAMETER ("GROUPID", "NAME", "VALUE") SELECT :GROUPID AS GROUPID, "NAME", "VALUE" FROM :FORECASTSLR_OUTPARAMETER;     END FOR;      RESULT=SELECT "GROUPID", "TIMESTAMP",CASE WHEN "VALUE"<0 THEN 0 ELSE "VALUE" END AS "VALUE" FROM #TEMPOUTPUTRESULT;     SELECT * FROM #TEMPOUTPARAMETER; END
